// Same build as the scenarios of the workshop, generated by scripts/export-preflight.sh. Do not edit.
// Building it once downloads everything the workshop build needs, so the room does not have to.


plugins {
    id("io.qalipsis.bootstrap") version "0.1.6"
}

description = "QALIPSIS scenarios of the DevOpsCon Munich 2026 workshop"
group = "io.qalipsis.workshop"
version = "1.0.0"

// JDK 21, like the QALIPSIS base image that runs the scenarios. Gradle downloads it when it is missing.
kotlin {
    jvmToolchain(21)
}

qalipsis {
    plugins {
        http()
        apacheKafka()
        sql()
        influxDb()
        // Meters and events in PostgreSQL, for the data series of the web interface of the QALIPSIS image.
        timescaleDb()
    }
}

dependencies {
    // Writes the orders as JSON.
    implementation("com.fasterxml.jackson.module:jackson-module-kotlin")
}

